/**
 * @file Firebase Realtime Database access for the ticket categories.
 */

import {
	child,
	type DataSnapshot,
	equalTo,
	get,
	onValue,
	orderByChild,
	push,
	query,
	ref,
	remove,
	update,
	type DatabaseReference,
	type Query
} from "firebase/database";
import type { Category } from "~/types";

/** Data provided by the caller: the id is the key generated by Firebase. */
export type NewCategory = Omit<Category, "id">;

/**
 * Access to the categories stored in the Realtime Database (`categories` node).
 *
 * Instantiate it in a composable or in the script setup of a page,
 * because the constructor calls `useNuxtApp()`.
 */
export class CategoryService {
	/** Reference to the `categories` node. */
	private categoriesRef: DatabaseReference;
	/** Reference to the `tickets` node, used to check that a category is unused before deleting it. */
	private ticketsRef: DatabaseReference;

	/** Gets the database provided by the Firebase plugin and points at the nodes in use. */
	constructor() {
		const { $db } = useNuxtApp();
		this.categoriesRef = ref($db, "categories");
		this.ticketsRef = ref($db, "tickets");
	}

	/**
	 * Converts a Firebase snapshot into a `Category` usable by the interface.
	 * Adds the id (the node key) and treats the category as active when the field is missing.
	 *
	 * @param snapshot - Snapshot of a category.
	 * @returns The converted category.
	 */
	private toCategory(snapshot: DataSnapshot): Category {
		const data = snapshot.val();
		return {
			id: snapshot.key!,
			name: data.name,
			active: data.active ?? true,
		};
	}

	/**
	 * Listens to a list of categories and converts it on every change.
	 *
	 * @param source - Node or query to listen to.
	 * @param callback - Receives the array of categories.
	 * @returns A function that stops listening.
	 */
	private watchList(source: Query, callback: (categories: Category[]) => void) {
		return onValue(source, (snapshot) => {
			const categories: Category[] = [];
			snapshot.forEach((categorySnapshot) => {
				categories.push(this.toCategory(categorySnapshot));
			});
			callback(categories);
		});
	}

	/**
	 * Creates a category with a key generated by Firebase.
	 *
	 * @param category - Name and state of the category, without id.
	 * @returns The reference of the created category; its id is in `.key`.
	 */
	create(category: NewCategory) {
		return push(this.categoriesRef, {
			name: category.name,
			active: category.active,
		});
	}

	/**
	 * Changes only the given fields (for example the name, or `active` to disable it).
	 *
	 * @param id - Id of the category to change.
	 * @param changes - Fields to change.
	 * @returns A promise resolved once the write is complete.
	 */
	update(id: string, changes: Partial<NewCategory>) {
		return update(child(this.categoriesRef, id), changes);
	}

	/**
	 * Enables or disables a category.
	 * A disabled category is no longer offered when creating a ticket,
	 * but the existing tickets keep it.
	 *
	 * @param id - Id of the category.
	 * @param active - `false` to disable it, `true` to enable it again.
	 * @returns A promise resolved once the write is complete.
	 */
	setActive(id: string, active: boolean) {
		return this.update(id, { active });
	}

	/**
	 * Permanently deletes a category, only if no ticket uses it
	 * (equivalent to `ON DELETE RESTRICT`). Meant to fix a category created by mistake;
	 * disable a category already in use with `setActive(id, false)` instead.
	 *
	 * @param id - Id of the category to delete.
	 * @returns A promise resolved once the deletion is complete.
	 * @throws Error if at least one ticket uses this category.
	 */
	async delete(id: string) {
		const linkedTickets = await get(query(this.ticketsRef, orderByChild("categoryId"), equalTo(id)));
		if (linkedTickets.exists()) {
			throw new Error("Impossible de supprimer : des tickets utilisent cette catégorie. Désactivez-la plutôt.");
		}
		return remove(child(this.categoriesRef, id));
	}

	/**
	 * Listens to all the categories in real time: the callback runs right away,
	 * then on every addition, change or deletion.
	 *
	 * @param callback - Receives the array of categories.
	 * @returns A function to call (for example in `onUnmounted`) to stop listening.
	 */
	list(callback: (categories: Category[]) => void) {
		return this.watchList(this.categoriesRef, callback);
	}

	/**
	 * Listens in real time to the active categories, those offered when creating a ticket.
	 *
	 * @param callback - Receives the array of active categories.
	 * @returns A function to call (for example in `onUnmounted`) to stop listening.
	 */
	listActive(callback: (categories: Category[]) => void) {
		return this.watchList(query(this.categoriesRef, orderByChild("active"), equalTo(true)), callback);
	}
}
